import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@^3.25.76";
var get_activity_default = defineTool2({
  name: "get_activity",
  title: "Detalle de actividad",
  description: "Devuelve la ficha t\xE9cnica completa de una actividad del cat\xE1logo a partir de su identificador.",
  inputSchema: {
    id: z2.string().min(1).describe("Identificador de la actividad, obtenido con list_activities.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const activity = allActivities().find((a) => a.id === id);
    if (!activity) throw new ToolError(`No existe ninguna actividad con id "${id}".`);
    return {
      content: [{ type: "text", text: JSON.stringify(activity, null, 2) }],
      structuredContent: { activity }
    };
  }
});

