// src/lib/mcp/tools/list-blog-posts.ts
var list_blog_posts_default = defineTool3({
  name: "list_blog_posts",
  title: "Listar art\xEDculos del blog",
  description: "Lista los art\xEDculos del blog con filtros opcionales por categor\xEDa y texto de b\xFAsqueda.",
  inputSchema: {
    category: z3.string().optional().describe("Categor\xEDa del art\xEDculo."),
    search: z3.string().optional().describe("Texto a buscar en t\xEDtulo, extracto o etiquetas."),
    limit: z3.number().int().min(1).max(50).default(10).describe("N\xFAmero m\xE1ximo de resultados.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, search, limit }) => {
    const q = search?.toLowerCase().trim();
    const posts = blogPosts.filter((p) => category ? p.category === category : true).filter(
      (p) => q ? `${p.title} ${p.excerpt} ${p.tags.join(" ")}`.toLowerCase().includes(q) : true
    ).slice(0, limit).map((p) => ({
      id: p.id,
      title: p.title,
      slug: p.slug,
      excerpt: p.excerpt,
      category: p.category,
      tags: p.tags,
      author: p.author.name,
      publishedAt: p.publishedAt,
      readTime: p.readTime
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(posts, null, 2) }],
      structuredContent: { count: posts.length, posts }
    };
  }
});

// src/lib/mcp/tools/get-blog-post.ts
import { defineTool as defineTool4, ToolError as ToolError2 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z4 } from "npm:zod@^3.25.76";
var get_blog_post_default = defineTool4({
  name: "get_blog_post",
  title: "Leer art\xEDculo del blog",
  description: "Devuelve el contenido completo de un art\xEDculo del blog a partir de su slug.",
  inputSchema: {
    slug: z4.string().min(1).describe("Slug del art\xEDculo, obtenido con list_blog_posts.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const post = blogPosts.find((p) => p.slug === slug);
    if (!post) throw new ToolError2(`No existe ning\xFAn art\xEDculo con slug "${slug}".`);
    return {
      content: [
        {
          type: "text",
          text: `# ${post.title}

${post.excerpt}

${post.content}`
        }
      ],
      structuredContent: {
        post: {
          title: post.title,
          slug: post.slug,
          category: post.category,
          author: post.author.name,
          publishedAt: post.publishedAt,
          content: post.content
        }
      }
    };
  }
});

